211: /** Produces a ShotCommand only: the bot never touches input devices or the physics world. */
212: export function planShot(profile: BotProfile, context: BotPlanningContext): BotPlan {
213:   const random = createSeededRandom(context.seed ?? `${profile.id}:${context.hole.id}:${context.clientSequence}`);
214:   const candidates = generateCandidates(context.hole, context.ballPosition, profile, random).sort((a, b) => b.score - a.score);
215:   const fallback = candidates[0] ?? cupCandidate(context.hole, context.ballPosition, profile);
216:   const poolSize = clamp(Math.round(2 + profile.skill.riskTolerance * 6), 1, Math.max(candidates.length, 1));
217:   const bias = 1 + (1 - profile.skill.riskTolerance) * 2;
218:   const pickIndex = Math.min(poolSize - 1, Math.floor(Math.pow(random(), bias) * poolSize));
219:   const chosenCandidate = candidates[pickIndex] ?? fallback;
220:   const angle = Math.atan2(chosenCandidate.direction.z, chosenCandidate.direction.x) + gaussian(random) * profile.skill.aimError * 0.45;
221:   const normalizedPower = clamp(chosenCandidate.normalizedPower * (1 + gaussian(random) * profile.skill.powerError), MIN_NORMALIZED_POWER, 1);
222:   const command: ShotCommand = {
223:     playerId: context.playerId,
224:     holeId: context.hole.id,
225:     direction: { x: Math.cos(angle), y: 0, z: Math.sin(angle) },
226:     normalizedPower,
227:     clientSequence: context.clientSequence,
228:     issuedAt: context.issuedAt,
229:   };
230:   return { command, chosenCandidate, candidates };
231: }
