116: /** Deterministic opponent field around a rating; synthesises extra bots for big lobbies. */
117: export function selectBotOpponents(targetRating: number, count: number, options: BotSelectionOptions = {}): BotProfile[] {
118:   const wanted = Math.max(0, Math.floor(count));
119:   if (wanted === 0) return [];
120:   const spread = options.spread ?? 160;
121:   const exclude = new Set(options.exclude ?? []);
122:   const random = createSeededRandom(options.seed ?? `field:${Math.round(targetRating)}:${wanted}`);
123:   const ranked = BOT_PROFILES
124:     .filter((profile) => !exclude.has(profile.id))
125:     .map((profile, index) => ({
126:       profile,
127:       index,
128:       weight: Math.abs(profile.rating + (random() - 0.5) * 2 * spread - targetRating),
129:     }))
130:     .sort((a, b) => (a.weight - b.weight) || (a.index - b.index));
131: 
132:   const chosen: BotProfile[] = ranked.slice(0, wanted).map((entry) => entry.profile);
133:   let extra = 0;
134:   while (chosen.length < wanted) {
135:     extra += 1;
136:     const offset = (extra % 2 === 0 ? 1 : -1) * Math.ceil(extra / 2) * 60;
137:     chosen.push(botProfileForRating(targetRating + offset, { id: `bot-field-${extra}` }));
138:   }
139: 
140:   const blend = options.tuneBlend ?? 0;
141:   const field = blend > 0 ? chosen.map((profile) => tuneProfileToRating(profile, targetRating, blend)) : chosen;
142:   return field.slice().sort((a, b) => b.rating - a.rating);
143: }
